css:
/* From Uiverse.io by Nawsome - Tags: switch */
.__UIV_SCOPE__ .checkbox {
  --border-default: #bbbbc1;
  --border-hover: #9898a3;
  --active: #6E7BF2;
  --active-tick: #ffffff;
  display: block;
  width: 18px;
  height: 18px;
  cursor: pointer;
  position: relative;
  -webkit-tap-highlight-color: transparent;
}

.__UIV_SCOPE__ .checkbox svg {
  display: block;
  position: absolute;
}

.__UIV_SCOPE__ .checkbox input {
  display: block;
  outline: none;
  border: none;
  padding: 0;
  margin: 0;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 36%/36%;
  box-shadow: inset 0 0 0 1.5px var(--border, var(--border-default));
  background: var(--background, transparent);
  transition: background 0.25s linear, box-shadow 0.25s linear;
}

.__UIV_SCOPE__ .checkbox input + svg {
  width: 21px;
  height: 18px;
  left: 0;
  top: 0;
  color: var(--active);
}

.__UIV_SCOPE__ .checkbox input + svg .tick {
  stroke-dasharray: 20;
  stroke-dashoffset: var(--stroke-dashoffset, 20);
  transition: stroke-dashoffset 0.2s;
}

.__UIV_SCOPE__ .checkbox input + svg .tick.mask {
  stroke: var(--active-tick);
}

.__UIV_SCOPE__ .checkbox input + svg + svg {
  width: 11px;
  height: 11px;
  fill: none;
  stroke: var(--active);
  stroke-width: 1.25;
  stroke-linecap: round;
  top: -6px;
  right: -10px;
  stroke-dasharray: 4.5px;
  stroke-dashoffset: 13.5px;
  pointer-events: none;
  -webkit-animation: var(--animation, none) 0.2s ease 0.175s;
  animation: var(--animation, none) 0.2s ease 0.175s;
}

.__UIV_SCOPE__ .checkbox input:checked {
  --background: var(--active);
  --border: var(--active);
}

.__UIV_SCOPE__ .checkbox input:checked + svg {
  --stroke-dashoffset: 0;
}

.__UIV_SCOPE__ .checkbox input:checked + svg + svg {
  --animation: check95;
}

.__UIV_SCOPE__ .checkbox:hover input:not(:checked) {
  --border: var(--border-hover);
}

@keyframes check95 {
  100% {
    stroke-dashoffset: 4.5px;
  }
}
